<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Holder\UserMfaRecoveryCodeVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserMfaRecoveryCodeVersionAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserMfaRecoveryCodeVersionAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getVersion returns null on a freshly created holder.
     */
    public function testVersionNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeVersionAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isVersionAssigned());
        $this->assertNull($holder->getVersion());
    }
}
class ImplWithUserMfaRecoveryCodeVersionAttributeHolderUnitTest
{
    use UserMfaRecoveryCodeVersionAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedVersionRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultVersion();
    }
}
